import React from 'react';
import './CursoDetalle.css'; // Estilos específicos
import Inscripcion from './Inscripcion'; // Formulario de inscripción

const CursoDetalle = () => {
  // Información del curso único
  const curso = {
    nombre: 'Curso de Trading Gratuito',
    descripcion:
      'Descubre los fundamentos del trading y cómo operar en los mercados financieros con <span class="highlight">Free Trader</span>. Aprende a analizar gráficos, gestionar riesgos y mucho más.',
    puntos: [
      'Acceso gratuito al contenido',
      'Introducción al análisis técnico',
      'Gestión emocional y de riesgo',
      'Comunidad privada en <span class="highlight">Instagram</span>',
      'Clases en video para principiantes',
    ],
    imagen: '/trading-icon.png', // Asegúrate de que esta imagen exista en la carpeta public
  };

  return (
    <div className="curso-container">
      <div className="curso-detalle">
        <h1 className="titulo-curso">
          {curso.nombre}
          <img src={curso.imagen} alt={curso.nombre} className="imagen-curso" />
        </h1>

        <p className="descripcion" dangerouslySetInnerHTML={{ __html: curso.descripcion }}></p>

        <ul>
          {curso.puntos.map((punto, index) => (
            <li key={index} dangerouslySetInnerHTML={{ __html: `✅ ${punto}` }}></li>
          ))}
        </ul>
      </div>

      <Inscripcion />
    </div>
  );
};

export default CursoDetalle;
